#include "domain/courtship.hpp"
#include "domain/nesting.hpp"
#include "engine/native_population_registry.hpp"
#include <iostream>
using namespace stalthos;using namespace stalthos::domain;using namespace stalthos::fauna;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{ActorView mate{2,HeroSpecies::Smalltrotter,{3,0,0},0,4000,0,.1,.1,.1,true,Activity::Rest};SmalltrotterCourtship court;check(!court.request(1,HeroSpecies::Smalltrotter,LifeStage::Hatchling,{0,0,0},true,{mate}),"immature invitation");check(!court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,{30,0,0},true,{mate})&&!court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,{0,0,0},true,{}),"remote/missing mate accepted");auto bad=mate;bad.alive=false;check(!court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,{0,0,0},true,{bad}),"dead mate accepted");bad=mate;bad.hunger=.9;check(!court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,{0,0,0},true,{bad}),"unavailable hungry mate accepted");check(court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,{0,0,0},true,{mate}),"local actual invitation");court.advance(1,{0,0,0},true,true,true,.1,{mate});check(!court.active()&&!court.acceptedMate(1),"direct interruption leaves readiness");court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,{0,0,0},true,{mate});court.advance(1,{0,0,0},true,false,false,.1,{mate});check(!court.ready(),"ordinary needs ignored");
std::vector<HabitatSite> sites{{{0,0,0},false,true,{1}},{{4,0,0},false,false,{0,2}},{{8,0,0},true,false,{1}}};Population p(42,1001,sites,1);auto state=p.snapshot();auto&a=state.actors[0];a.species=HeroSpecies::Smalltrotter;a.calendarAge=4000;a.stage=LifeStage::Adult;a.site=0;a.target=0;a.position=sites[0].position;a.activity=Activity::Rest;a.hunger=.1;a.thirst=.1;a.fatigue=.1;p.restore(state);ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,2},{200,ResourceKind::Shrub,10,1}},{{90,100,2},{91,200,1}}};uint64_t next=100;engine::NativePopulationRegistry host(p,ledger,{},{{0,100,sites[0].position},{2,200,sites[2].position}},next);auto oldBindings=host.sessions();Vec3 body{8,0,0};court=SmalltrotterCourtship{};check(court.request(1,HeroSpecies::Smalltrotter,LifeStage::Adult,body,true,host.actors()),"real registry mate invitation");int frames=0;for(;frames<200&&!court.ready();++frames){host.advance({.1,.1},true,BodyAwareness{body,{},court.mate(),3.25,false,true});court.advance(1,body,true,true,false,.1,host.actors());}check(court.ready()&&court.acceptedMate(1)==a.id&&frames>20,"readiness without sustained actual response");check(host.actors()[0].position.x>4.7&&host.actors()[0].distanceTravelledMeters>4.7&&host.actors()[0].id==a.id&&std::abs(host.actors()[0].calendarAge-(4000+frames*.1))<1e-7,"no actual mate motion or duplicate clock");auto after=host.ledger();check(host.sessions()==oldBindings&&after.sessions.size()==2&&after.sessions[0].amount==2&&after.sessions[1].amount==1&&after.resources[0].consumedQuantity==2&&after.resources[1].consumedQuantity==1,"response altered history/session ownership");check(court.currentMateReady(body,host.actors()),"late actual mate not ready");auto disappeared=host.actors();disappeared[0].position.x=30;check(!court.currentMateReady(body,disappeared),"late departed mate accepted");Nesting nest;NestSite site{{9.9,0,0},true,true,true,0};check(!nest.lay(1,HeroSpecies::Smalltrotter,LifeStage::Adult,.1,.1,.1,site,100),"ordinary mate-less clutch still possible");check(nest.lay(1,HeroSpecies::Smalltrotter,LifeStage::Adult,.1,.1,.1,site,100,court.acceptedMate(1))&&nest.clutch()->mate==a.id,"accepted actual mate not stored");check(!court.acceptedMate(99),"new hero inherited mate readiness");court.advance(1,body,true,true,false,.1,{});check(!court.ready()&&!court.acceptedMate(1),"lost mate leaves readiness");std::cout<<"COURTSHIP_REVIEW_OK actual_registry_response_onceclock_history_local_refusals_priority_mate_gated_clutch\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

